def parse(s): return [[int(x) for x in row.split()] for row in s.splitlines()]
def transform(g):
    from collections import Counter
    counts=Counter(x for row in g for x in row)
    bg=counts.most_common(1)[0][0]
    keep={c for c,n in counts.most_common() if c!=bg}
    keep=set(sorted(keep,key=lambda c:counts[c],reverse=True)[:2])|{bg}
    return [[x if x in keep else bg for x in row] for row in g]
