def component_sizes(g):
    h,w=len(g),len(g[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if (r,c) in seen: continue
        col=g[r][c]; st=[(r,c)]; seen.add((r,c)); comp=[]
        while st:
          x,y=st.pop(); comp.append((x,y))
          for dx,dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            xx,yy=x+dx,y+dy
            if 0<=xx<h and 0<=yy<w and (xx,yy) not in seen and g[xx][yy]==col:
              seen.add((xx,yy)); st.append((xx,yy))
        comps.append((col,len(comp),comp))
    return comps
